    [1651] = { "Le Tome de la bravoure", "Défendez Daphne Morpuits contre les attaques des Défias.\n\nAucun de vous deux ne doit mourir, si vous voulez réussir la quête.\n\nQuand vous aurez réussi, reparlez à Daphne Morpuits." },
