    [2200] = { "Retour à Uldaman", "Chercher des indices sur le Collier de Talvash à Uldaman. Le paladin dont il a parlé est la dernière personne à l'avoir porté." },
    [2201] = { "Trouver les gemmes", "Trouvez le rubis, le saphir et la topaze qui sont éparpillés à travers Uldaman. Une fois que vous les aurez, contactez Talvash del Kissel en utilisant la Flasque de divination qu’il vous a donnée précédemment.\n\nC'est dans le journal, vous savez...\n* Le rubis a été caché dans une zone barricadée des Ombreforge.\n* La topaze a été dissimulée dans une urne, dans l’une des zones trogg, pas très loin de nains de l’Alliance.\n* Le saphir est en la possession du chef trogg, Grimelok." },
    [2202] = { "Rechercher les composants à Uldaman", "Apporter 12 Champignons magenta à Jarkal Fondemousse à Kargath." },
    [2203] = { "Les réactifs des Terres ingrates II", "Utiliser les 3 Récipients thaumaturgiques vides sur des dragons gardiens des terres brûlées dans les Terres ingrates. Une fois remplis, les rapporter à Jarkal Fondemousse à Kargath." },
