    [2339] = { "Trouver les gemmes et la source d'énergie", "Récupérer, dans Uldaman, les trois gemmes et une source d’énergie pour le collier, puis les rapporter à Jarkal Fondemousse, à Kargath. Jarkal pense que vous pouvez trouver une source d’énergie sur la machine la plus puissante d’Uldaman.\n\nC'est dans le journal, vous savez...\n* Le rubis a été caché dans une zone barricadée des Ombreforge.\n* La topaze a été dissimulée dans une urne, dans l’une des zones trogg, pas très loin de nains de l’Alliance.\n* Le saphir est en possession du chef trogg, Grimelok." },
    [2340] = { "Livrer les Gemmes", "Apporter les Gemmes et le Collier récupérés à Dran Droffers, à Orgrimmar." },
    [2341] = { "Réparer le collier, troisième prise", "Rendre visite à Jarkal Fondemousse à Kargath pour constater (ou non) son succès." },
