    [2501] = { "Les réactifs des Terres ingrates II", "Utiliser les Récipients thaumaturgiques vides sur des dragons gardiens des terres brûlées dans les Terres ingrates. Une fois remplis, les rapporter à Ghak Touchesoins à Thelsamar." },
    [2745] = { "En infiltrant le château", "Allez voir Tyrion au Château de Hurlevent." },
    [2746] = { "Des objets d’une certaine importance", "Apporter 3 Etoffes de soie et 2 Pommes fraîches de Clara à Tyrion à Hurlevent." },
    [2768] = { "Le bâtonnet divino-matic", "Apportez le Bâtonnet divino-matic à l'Ingénieur en chef Vizisanie, à Gadgetzan." },
    [2770] = { "Gahz'rilla", "Rapporter l'Ecaille électrifiée de Gahz'rilla à Lachnouf Zéboulon dans les Salines." },
    [2841] = { "Guerre des plates-formes", "Obtenez la Combinaison du coffre de Thermojoncteur, prenez les Plans de la plateforme à Gnomeregan et apportez-les à Nogg, à Orgrimmar." },
    [2842] = { "L'ingénieur en chef Scooty", "Parler à Scooty à Baie-du-Butin." },
    [2843] = { "Gnomer-paaarti !", "Attendre que Scooty calibre le Transpondeur gobelin." },
    [2846] = { "La tiare des abysses", "Apportez la Tiare des abysses à Tabetha au marécage d'Âprefange." },
    [2865] = { "Les carapaces de scarabées", "Rapporter 5 Carapaces de scarabée intactes à Tran'rek à Gadgetzan." },
    [2904] = { "Une jolie pagaille", "Escorter Kernobee jusqu’à la sortie de la Fuite du temps, puis faire un rapport à Scooty, à Baie-du-Butin." },
    [2922] = { "Sauver le cerveau de Techbot !", "Rapportez la Mémoire principale de Techbot au maître-artisan Suprétincelle à Forgefer." },
    [2924] = { "Les cerveaux mécaniques", "Rapporter 12 Cerveaux mécaniques à Pléthorloge Cléventail à Forgefer." },
    [2926] = { "Gnogaine", "Utiliser la Flasque de collecte plombée vide sur les Envahisseurs ou les Pilleurs irradiés pour recueillir des retombées radioactives. Une fois pleine, rapportez-la à Ozzie Virevolt à Kharanos." },
    [2928] = { "Excavateurs gyrodrilmatiques", "Apportez 24 Entrailles mécaniques de robot à Shoni, à Hurlevent." },
    [2929] = { "La grande trahison", "Aller à Gnomeregan et tuer le mekgénieur Thermojoncteur. Puis retourner voir le Grand Bricoleur Mekkanivelle." },
    [2930] = { "Sauvetage de données", "Apporter une Carte perforée prismatique au Maître mécanicien Fontuyau, à Forgefer." },
    [2933] = { "Bouteilles de venin", "Apporter une Bouteille de venin à un apothicaire, à Moulin-de-Tarren." },
    [2934] = { "Glande à venin intacte", "Rapporter une Glande à venin intacte à l'Apothicaire Lydon, à Moulin-de-Tarren." },
    [2935] = { "Consulter Maître Gadrin", "Parler à Maître Gadrin au village de Sen'jin." },
    [2936] = { "Le dieu-araignée", "Lire la Tablette de Theka pour connaître le véritable nom du dieu-araignée des Fanécorces, puis retourner voir Maître Gadrin." },
    [2937] = { "L'invocation de Shadra", "Terrasser Shadra, à l'autel de Shadra'Alor, puis rapporter son venin à l'Apothicaire Lydon, à Moulin-de-Tarren." },
    [2938] = { "Du venin pour Fossoyeuse", "Apporter le Colis de Faranell au maître apothicaire Faranell, à Fossoyeuse." },
    [2945] = { "Anneau sali", "Trouver un moyen de nettoyer l'Anneau sali." },
    [2946] = { "Questions sans réponses", "Apportez les Disques de platine miniatures aux Portes d'Uldum, à Tanaris, et cherchez les indices de la connexion qui existe entre eux." },
    [2947] = { "Le retour de l'anneau", "Vous pouvez soit garder l'anneau, soit retrouver la personne désignée par les lettres qui sont gravées à l'intérieur." },
    [2948] = { "Amélioration gnomique", "Apportez l’Anneau d’or brillant, une Barre d’argent, une Agate mousse et 30 pièces d’argent à Talvash del Kissel, à Forgefer." },
    [2949] = { "Le retour de l'anneau", "Vous pouvez soit garder l'anneau, soit retrouver la personne désignée par les lettres qui sont gravées à l'intérieur." },
    [2950] = { "Nogg améliore l’anneau", "Apportez l’Anneau d’or brillant, une Barre d’argent, une Agate mousse et 30 pièces d’argent à Nogg, à Orgrimmar." },
    [2951] = { "Le Brille-o-Matic 5200 !", "Insérer un Objet sali dans le Brille-o-Matic 5200, sans oublier de jeter trois pièces d'argent dans la fente, pour démarrer la machine." },
    [2952] = { "Le Brille-o-Matic 5200 !" },
    [2953] = { "Le Brille-o-Matic décape encore" },
    [2954] = { "Le Gardien des pierres", "Apprendre le but du Gardien des pierres de Norgannon, puis interagir avec le Piédestal d'Uldum, dans le désert de Tanaris." },
    [2962] = { "Encore plus de Lueur verte !", "Voyager à Gnomeregan et rapporter de la Matière radioactive à haut potentiel. Attention, la matière radioactive est instable et se désactive rapidement.\n\nUne fois la tâche achevée, conserver la Flasque plombée lourde, pour Ozzie." },
    [2963] = { "Prodiges d'Uldum", "Parler à l'Historien Karnik dans le Hall des explorateurs, à Forgefer." },
    [2964] = { "Travail imminent", "Parler au Grand Explorateur Magellas, à Forgefer." },
    [2965] = { "Prodiges d'Uldum", "Aller à la Cime des Anciens, aux Pitons-du-Tonnerre et parler à Nara Crin-Sauvage." },
    [2966] = { "Questions sans réponses", "Apportez les Disques de platine miniatures aux Portes d'Uldum, à Tanaris, et cherchez les indices de la connexion qui existe entre eux." },
    [2967] = { "Le retour aux Pitons-du-Tonnerre", "Parler à Nara Crin-Sauvage, aux Pitons-du-Tonnerre." },
    [2968] = { "Travail imminent", "Parler au Sage Recherche-la-Vérité, aux Pitons-du-Tonnerre." },
    [2977] = { "Retour à Forgefer", "Parler à l'Historien Karnik, à Forgefer." },
    [2988] = { "Les cages des Fanécorces", "Inspectez les cages dans les deux villages des Fanécorces, puis retournez auprès du Maître des griffons Hachegriffe." },
    [2989] = { "L'autel de Zul", "Regarder sur le dessus de l'autel de Zul, puis retourner auprès du Maître des griffons Hachegriffe." },
    [2990] = { "Thadius Sinissombre", "Apportez la Plume de Bec-tranchant à Thadius Sinissombre, dans les Terres Foudroyées." },
    [2991] = { "Le médaillon de Nekrum", "Apportez le Médaillon de Nekrum à Thadius Sinissombre, dans les Terres Foudroyées." },
    [2992] = { "La Divination", "Attendre que Sinissombre ait fini de pratiquer son rituel de divination." },
    [2993] = { "Retour dans les Hinterlands", "Parler au Maître des griffons Hachegriffe." },
    [2994] = { "Sauver Bec-tranchant", "Combattre jusqu’au sommet de Jintha'Alor, tuer la vile prêtresse Maléficia pour obtenir la clé de la cage de Bec-tranchant, et sauver Bec-tranchant." },
    [3042] = { "Agent durcissant troll", "Apporter 20 Fioles d'agent durcissant troll à Trenton Martelume, à Gadgetzan." },
    [3341] = { "L'anéantissement", "Andrew Brownell veut que vous tuiez Amnennar le Porte-froid et que vous lui rameniez son crâne." },
    [3369] = { "Au cœur des cauchemars", "Apportez l'Éclat de cauchemar à Hamuul Totem-runique à la Cime des Anciens." },
    [3370] = { "Au cœur des cauchemars", "Apportez l'Éclat de cauchemar à Mathrengyl Pasdelours à Darnassus." },
    [3373] = { "L'Essence d'Eranikus", "Placer l'Essence d'Eranikus dans le Réceptacle d'essence situé dans son antre dans le Temple englouti." },
    [3374] = { "L'Essence d'Eranikus", "Apportez la Pierre de voeu des dragons d'Ysera et l'Essence d'Eranikus enchaînée à Itharius au marais des Chagrins. C'est là que vous choisirez d'aider ou non les dragons d'Ysera." },
    [3375] = { "La flasque de remplacement", "Apportez une Potion de mana, du Charbon, et du Nectar sucré à Talvash del Kissel, à Forgefer, pour remplacer la Flasque de divination de Talvash." },
    [3380] = { "Le Temple englouti", "Trouver Marvon Chercherivet à Tanaris." },
    [3441] = { "Châtiment divin", "Écouter le récit de Kalaran Lamevent." },
    [3442] = { "La flamme parfaite", "Réunir 4 Cœurs des flammes et 4 globes d'Huile de golem puis rapporter ces objets à Kalaran Lamevent." },
    [3443] = { "Forger le manche", "Apporter 8 Dagues plaquées en thorium à Kalaran Lamevent." },
    [3444] = { "Le Cercle de pierres", "Récupérer le Cercle de pierres à l'Atelier de Marvon Chercherivet à Cabestan." },
    [3445] = { "Le Temple englouti", "Trouver Marvon Chercherivet à Tanaris." },
    [3446] = { "Dans les profondeurs", "Trouver l'Autel d'Hakkar dans le Temple englouti du marais des Chagrins." },
    [3447] = { "Le secret du cercle", "Voyager jusqu'au Temple englouti et découvrir le secret du cercle de statues." },
    [3452] = { "L'enveloppe de la flamme", "Trouver et apporter un Symbole de Ragnaros à Kalaran Lamevent." },
    [3453] = { "La Torche de vindicte", "Attendre que Kalaran Lamevent termine la Torche de vindicte." },
    [3454] = { "La Torche de vindicte", "Prendre la Torche de vindicte." },
    [3462] = { "L'écuyer Maltrake", "Parler à l'écuyer Maltrake." },
    [3463] = { "Allumer le feu !", "Mettre le feu aux Tours de garde nord, sud, est et ouest en utilisant la Torche de vindicte à l'intérieur de chaque tour." },
    [3481] = { "Bibelots...", "Ouvrir le coffre." },
    [3512] = { "Par les mots d'Eranikus", "Rendez-vous dans la partie orientale du Berceau-de-l'Hiver et allez voir Umbranse l'implorateur d'esprit." },
    [3520] = { "Esprits de Hurleurs", "Capturer l’Esprit de 3 Hurleurs en Féralas, puis retourner voir Yeh'kinya à Port Gentepression." },
    [3523] = { "Le Fléau des Souilles", "Pour aider Belnistrasz, lui parler de nouveau et lui rendre la Pierre de voeu qu’il vous avait donnée." },
    [3525] = { "L'extinction de l'idole", "Escorter Belnistrasz jusqu'à l'Idole des hurans dans les Souilles de Tranchebauge.\n\nProtéger Belnistrasz tandis qu'il exécute le rituel pour arrêter l'idole." },
    [3527] = { "La prophétie de Mosh'aru", "Apportez les Première et Deuxième tablettes Mosh'Aru à Yeh'kinya, à Tanaris." },
    [3528] = { "Le dieu Hakkar", "Apportez l’Œuf d'Hakkar rempli à Yeh'kinya dans Tanaris." },
    [3636] = { "Apportez la Lumière", "Tuer Amnennar le Porte-froid, aux Souilles de Tranchebauge, pour l’Archevêque Benedictus." },
    [3701] = { "Les ruines fumantes de Thaurissan", "Allez dans les ruines de Thaurissan, dans les Steppes Ardentes. Récupérez des informations sur les Reliques de Thaurissan, puis retournez auprès de l’Historienne royale Archesonus." },
    [3702] = { "Les ruines fumantes de Thaurissan", "Écouter l'historienne royale Archesonus raconter l'histoire de Thaurissan." },
    [3765] = { "La dépravation au loin", "Aller voir Gershala Murmenuit à Auberdine." },
    [3801] = { "Héritage Sombrefer", "Parler à Franclorn Le Forgebusier à la Tombe du Forgebusier, au Mont Rochenoire, si obtenir une clé de la Cité majeure vous intéresse." },
    [3802] = { "Héritage Sombrefer", "Tuer Fineous Sombrevire et récupérer le grand marteau, Souillefer. Apporter Souillefer au sanctuaire de Thaurissan et le placer sur la statue de Franclorn Le Forgebusier." },
    [3906] = { "Discordance des flammes", "Partir pour la carrière dans le mont Rochenoire et tuer le Grand maître Pyron. Retourner voir Cœur-de-tonnerre une fois votre mission accomplie." },
    [3907] = { "Discordance des flammes", "Pénétrez dans les Profondeurs de Rochenoire et traquez le Seigneur Incendius. Tuez-le puis donner tous les renseignements que vous pourrez trouver à Cœur-de-tonnerre." },
    [3981] = { "Le commandant Gor'shak", "Trouver le commandant Gor'shak dans les Profondeurs de Rochenoire.\n\nVous vous souvenez que le dessin maladroit représentait également des barreaux au-dessus du portrait. Peut-être devriez-vous rechercher un genre de prison." },
    [3982] = { "Que se passe-t-il ?", "Défendre Gor'shak." },
    [4001] = { "Que se passe-t-il ?", "Parler à Kharan Force-martel et obtenir autant de renseignements que possible sur l'enlèvement de la princesse Moira Barbe-de-bronze. Apporter ces renseignements à Thrall à Orgrimmar.\n\nGor'shak a dit que Kharan était détenu dans une cellule proche." },
    [4002] = { "Les royaumes de l'Est", "Parler à Thrall si vous êtes $gprêt:prête; à vous charger de la mission qu'il a prévue." },
    [4003] = { "Un sauvetage royal", "Tuer l'Empereur Thaurissan et libérer la Princesse Moira Barbe-de-bronze de son sort maléfique." },
    [4004] = { "La Princesse sauvée ?", "Retourner voir Thrall à Fort Grommash, à Orgrimmar." },
    [4022] = { "Un goût de flammes", "Montrer à Cyrus Lerepenti l'Ecaille des dragons noirs que vous avez reçue de Kalaran Lamevent." },
    [4023] = { "Un goût de flammes", "Montrer à Cyrus Lerepenti une preuve de votre valeur.\n\nVous avez le sentiment que Cyrus sait déjà que vous êtes indigne." },
    [4024] = { "Un goût de flammes", "Partez pour les Profondeurs de Rochenoire et tuez Bael'Gar.\n\nVous savez seulement que le géant demeure à l'intérieur des Profondeurs de Rochenoire. N'oublier pas d'utiliser l'Ecaille des dragons noirs altérée pour capturer l'Essence ardente.\n\nApporter l'Essence ardente recouverte à Cyrus Lerepenti." },
    [4061] = { "La révolte des machines", "Aventurez-vous dans les Steppes Ardentes et récupérez 10 Fragments d'élémentaires cassés pour la Hiérophante Theodora Mulvadania.\n\nTheodora vous a indiqué que les golems et les élémentaires étaient la source de ces fragments." },
    [4062] = { "La révolte des machines", "Apporter l'Échantillon de fragment d'élémentaire à Lotwil Veriatus.\n\nTheodora vous a dit qu'il se trouvait dans un camp à l'est." },
    [4063] = { "La révolte des machines", "Trouver et tuer le Seigneur des golems Argelmach. Rapporter sa tête à Lotwil. Collecter également 10 Noyaux d'élémentaire intacts sur les Golems ravarage et les Assemblages porteguerre qui protègent Argelmach. Vous savez cela car vous êtes médium." },
    [4081] = { "TUER À VUE : nains sombrefers", "Pénétrez dans les Profondeurs de Rochenoire et tuez les vils agresseurs !\n\nLe chef de guerre Sangredent veut que vous tuiez 15 Gardes ragenclumes, 10 Gardiens ragenclumes et 5 Fantassins ragenclumes. Retourner le voir une fois votre mission accomplie." },
    [4082] = { "TUER À VUE : Officiers de haut rang sombrefers", "Pénétrez dans les Profondeurs de Rochenoire et tuez les vils agresseurs !\n\nLe Chef de guerre Sangredent veut que vous tuiez 10 Médecins ragenclumes, 10 Soldats ragenclumes et 10 Officiers ragenclumes. Retourner le voir une fois votre mission accomplie." },
    [4121] = { "Situation précaire", "Escortez votre prisonnier, Grark Lorkrub, au-delà des Steppes ardentes et du mont Rochenoire, jusqu'à la gorge des Vents brûlants.\n\nRappelez-vous que Lexlort a précisé que ses hommes attendraient de l'autre côté pour arrêter Grark.\n\nOn vous demandera également de remettre vos chaînes en thorium à Lexlort." },
    [4122] = { "Grark Lorkrub", "Partez pour les Steppes Ardentes et trouvez Grark Lorkrub. Lexlort vous a dit qu'il a été vu pour la dernière fois dans une imposante forteresse des Rochenoires.\n\nUne fois que vous aurez trouvé Grark Lorkrub, enchaînez-le avec les Chaînes en thorium, puis ramenez-le par le mont Rochenoire jusque dans la gorge des Vents brûlants. Des hommes de Lexlort attendront de l'autre côté et le mettront sous bonne garde." },
    [4123] = { "Le Cœur de la montagne", "Apportez le Cœur de la montagne à Maxwort Uberbrille dans les Steppes Ardentes." },
    [4126] = { "Hurley Soufflenoir", "Apportez la Recette perdue de la Tonnebière à Ragnar Tonnebière, à Kharanos." },
    [4132] = { "Opération : Mort à Forgehargne", "Voyagez jusqu'aux Profondeurs de Rochenoire et tuez le général Forgehargne ! Une fois votre mission accomplie, retournez voir le seigneur de guerre Sangredent." },
    [4134] = { "La recette perdue de Tonnebière", "Apportez la Recette perdue de la Tonnebière à Vivian Lagrave à Kargath." },
    [4136] = { "Ribbly Fermevanne", "Apportez la Tête de Ribbly à Yuka Fermevanne, dans les Steppes Ardentes." },
    [4141] = { "Muigin et Larion", "Récolter 15 Pétales-de-sang et retourner voir Muigin." },
    [4142] = { "Visite à Gregan", "Apporter un Pétale-de-sang à Gregan Gerbebière en Féralas." },
    [4143] = { "Brouillard maléfique", "Récupérez 5 Échantillons de brume atal'ai puis retournez voir Muigin dans le cratère d'Un'Goro." },
    [4144] = { "Les pousses de Pétales-de-sang" },
    [4145] = { "Larion et Muigin", "Chasser 5 Flagellants Pétale-de-sang, 5 Batteurs Pétale-de-sang, 5 Ecorcheurs Pétale-de-sang et 5 Trappeurs Pétale-de-sang pour Larion au refuge des Marshal." },
    [4146] = { "Carburant de baguette", "Remettre la Baguette déchargée et 5 Échantillons de brume atal'ai à Larion au refuge des Marshal." },
    [4147] = { "Atelier de Marvon", "Se rendre à l'Atelier de Marvon Chercherivet à Cabestan." },
    [4148] = { "La baguette Pétale-de-sang" },
    [4182] = { "La menace des draconiens", "Tuer 15 Rejetons noirs, 10 Draconides noirs, 4 Wyrmides noirs et 1 Drake noir." },
    [4183] = { "Les véritables maîtres", "Voyager jusqu'à Comté-du-Lac, dans les Carmines et remettre la Lettre d'Helendis Ruissecorne au Magistrat Salomon." },
    [4184] = { "Les véritables maîtres", "Voyager jusqu'à Hurlevent et remettre la Demande d'aide de Salomon au roi Varian Wrynn.\n\nLe roi demeure au Donjon de Hurlevent." },
    [4185] = { "Les véritables maîtres", "Parler au généralissime Bolvar Fordragon après avoir parlé à dame Katrana Prestor." },
    [4186] = { "Les véritables maîtres", "Apporter le Décret de Wrynn au Magistrat Salomon à Comté-du-Lac." },
    [4201] = { "Le philtre d'amour", "Apporter 4 Gromsang, 10 Veines d'argent de géant et la Fiole de Nagmara remplie à la gouvernante Nagmara dans les Profondeurs de Rochenoire." },
    [4223] = { "Les véritables maîtres", "Parlez au maréchal Maxwell dans les Steppes Ardentes." },
    [4224] = { "Les véritables maîtres", "Allez voir John le Loqueteux." },
    [4241] = { "Maréchal Windsor", "Partir pour le mont Rochenoire au nord-ouest et pénétrer dans les Profondeurs de Rochenoire. Découvrir ce qu'il est advenu du Maréchal Windsor.\n\nVous vous souvenez que John le Loqueteux a dit que Windsor avait été traîné en prison." },
    [4242] = { "Espoir abandonné", "Apportez les mauvaises nouvelles au Maréchal Maxwell à la Veille de Morgan, dans les Steppes Ardentes." },
    [4262] = { "Grand seigneur Pyron", "Tuer le Grand seigneur Pyron.\n\nJalinda vous a dit qu'il gardait la carrière. Peut-être devriez-vous chercher à cet endroit ?" },
    [4263] = { "Incendius !", "Trouver le Seigneur Incendius dans les Profondeurs de Rochenoire et le détruire !" },
    [4264] = { "Une note chiffonnée", "Il se peut que vous ayez simplement buté sur quelque chose qui pourrait intéresser le maréchal Windsor au plus haut point. Il reste peut-être encore un peu d'espoir, après tout…" },
    [4282] = { "Un espoir en lambeaux", "Rapporter les Informations égarées du maréchal Windsor.\n\nLe maréchal Windsor pense qu'ils sont détenus par le seigneur golem Argelmach et par le général Forgehargne." },
    [4286] = { "Du beau matériel", "Trouvez 20 Sacoches Sombrefer." },
    [4322] = { "Évasion !", "Aider le maréchal Windsor à récupérer son équipement et à libérer ses amis. Ensuite, retourner voir le maréchal Maxwell." },
    [4341] = { "Kharan Force-martel", "Allez dans les Profondeurs de Rochenoire et trouvez Kharan Force-martel.\n\nLe roi a mentionné que Kharan était retenu prisonnier là-bas ; cherchez une prison." },
    [4342] = { "Légende de Kharan", "Écouter Kharan Force-martel raconter son histoire." },
    [4361] = { "Le porteur des mauvaises nouvelles", "Retourner à Forgefer et apporter la mauvaise nouvelle au Roi Magni Barbe-de-bronze." },
    [4362] = { "Le destin du Royaume", "Retourner dans les Profondeurs de Rochenoire et secourir la Princesse Moira Barbe-de-bronze, prisonnière de l'Empereur Dagran Thaurissan." },
    [4363] = { "La surprise de la Princesse", "Retourner à Forgefer et parler au roi Magni Barbe-de-bronze." },
    [4601] = { "Le Brille-o-Matic 5200 !", "Insérer un Objet sali dans le Brille-o-Matic 5200 et s'assurer d'avoir trois pièces d'argent pour démarrer la machine." },
    [4602] = { "Le Brille-o-Matic 5200 !", "Insérer un Objet sali dans le Brille-o-Matic 5200 et s'assurer d'avoir trois pièces d'argent pour démarrer la machine." },
    [4603] = { "Le Brille-o-Matic décape encore" },
    [4604] = { "Le Brille-o-Matic décape encore" },
    [4605] = { "Le Brille-o-Matic 5200 !" },
    [4606] = { "Le Brille-o-Matic 5200 !" },
    [4701] = { "Abattez-la", "Allez au Pic Rochenoire et anéantissez la source de la menace. Quand vous avez quitté Helendis, il a crié un nom : Halycon. C'est ce que disent les orcs en parlant des worgs." },
    [4724] = { "La maîtresse de meute", "Tuer Halycon, la maîtresse de la meute des worgs haches-sanglantes." },
    [4726] = { "L'essence de rejeton", "Apportez 8 Essences de Rejeton et le Draco-Incarcinatrix 900 à Brikolette Toutevapeur à la Corniche des Flammes, dans les Steppes Ardentes." },
    [4729] = { "Les animaux exotiques de Kibler", "Allez au Pic Rochenoire et trouvez de Jeunes worgs haches-sanglantes. Utilisez la cage pour transporter ces petites bêtes féroces. Rapportez un Jeune worg en cage à Kibler." },
    [4734] = { "Un oeuf congelé", "Utiliser le Prototype d’Œufilloscope sur un œuf dans la Colonie au Pic Rochenoire." },
    [4735] = { "La collecte d’œufs", "Apportez 8 Œufs de dragon collectés et le Module collectronique à Brikolette Toutevapeur à la Corniche des Flammes, dans les Steppes Ardentes." },
    [4742] = { "Le sceau d'ascension", "Trouver les trois gemmes de commandement : la Gemme de Brûleronce, la Gemme de Pierre-du-pic et la Gemme de Hache-sanglante. Rapportez-les, ainsi que le Sceau d'ascension non décoré, à Vaelan.\n\nLes généraux, comme vous l'a dit Vaelan, sont : le maître de guerre Voone de Brûleronce ; le généralissime Omokk des Pierres-du-pic ; et le seigneur Wyrmthalak de Hache-sanglante." },
    [4743] = { "Le sceau d'ascension", "Allez à la tourbière du Ver dans le marécage d'Âprefange. Trouvez l'ancien drake, Brandeguerre, et frappez-le sans merci jusqu'à ce que sa volonté soit brisée.\n\nÀ cet instant précis, vous devez placer le Sceau d'ascension brut devant l'énorme bête. Vous devez ensuite utiliser rapidement l'Orbe d'énergie draconique sur sa forme affaiblie et prendre possession de ses facultés mentales. Contrôlez la bête et dirigez les flammes du Vol noir sur le Sceau d'ascension brut !" },
    [4764] = { "Le fermoir de Frèteruine", "Apportez le Fermoir de Frèteruine à Mayara Luisaile, dans les Steppes Ardentes." },
    [4765] = { "La livraison à Bellornière", "Apporter la Caisse de Bellornière au Comte Remington Bellornière au Donjon de Hurlevent, à Hurlevent." },
    [4768] = { "La tablette de Sombrepierre", "Apportez la Tablette de Sombrepierre à l'ombremage Vivian Lagrave à Kargath." },
    [4771] = { "Le gambit de l'aube", "Placer le Gambit de l'aube dans la Chambre des visions de Scholomance. Vaincre Vectus, puis retourner auprès de Betina Bigglezink." },
    [4787] = { "L'œuf antique", "Apportez l’Œuf antique à Yeh'kinya à Tanaris." },
    [4788] = { "Les dernières tablettes", "Apportez la Cinquième et la Sixième tablette Mosh'aru au Prospecteur Botte-de-fer, en Tanaris." },
    [4808] = { "Felnok Ressordacier", "Donner la Lettre de Brikolette à Felnok Ressordacier à Long-Guet, à Berceau-de-l'Hiver." },
    [4809] = { "Cornes de Noroît", "Collectez 8 Cornes intactes de Noroît." },
    [4810] = { "Retourner voir Brikolette", "Apportez le Paquet de Felnok à Brikolette Toutevapeur à la Corniche des Flammes, dans les Steppes Ardentes." },
    [4862] = { "Mauvais", "Aller au Pic Rochenoire et ramasser 15 Œufs d'araignée du pic pour Kibler.\n\nCes œufs peuvent être trouvés à proximité des araignées." },
    [4866] = { "Le lait matriarcal", "Vous trouverez la Matriarche Couveuse au cœur du pic Rochenoire. Attaquez-la et poussez-la à vous empoisonner. Vous devrez sans doute la tuer. Une fois $gempoisonné:empoisonnée;, trouvez John le Loqueteux afin qu'il puisse prélever un échantillon." },
    [4867] = { "Urok Hurleruine", "Lire le Parchemin de Warosh. Apporter le Mojo de Warosh à Warosh." },
    [4903] = { "Ordre du seigneur de guerre", "Tuer le généralissime Omokk, le maître de guerre Voone et le seigneur Wyrmthalak. Récupérer les Importants documents Rochenoire. Retourner voir le chef de guerre Sangredent à Kargath une fois la mission accomplie." },
    [4941] = { "Sagesse d'Eitrigg", "Parler à Eitrigg, à Orgrimmar. Après avoir discuté avec Eitrigg, demander conseil à Thrall.\n\nVous avez déjà vu Eitrigg dans les Appartements de Thrall." },
    [4974] = { "Pour la Horde !", "Aller au Pic Rochenoire et tuer le Chef de guerre, Rend Main-noire. Prendre sa tête et retourner à Orgrimmar." },
    [4981] = { "Agent Bijou", "Allez au Pic Rochenoire et découvrez ce qui est arrivé à Bijou." },
    [4982] = { "Les affaires de Bijou", "Trouvez les Affaires de Bijou et rapportez-les-lui. Elle vous a dit les avoir cachées dans le niveau inférieur de la ville." },
    [4983] = { "Rapport de reconnaissance de Bijou", "Rapporter le Rapport de reconnaissance de Bijou au Grand-maître Lexlort, à Kargath." },
    [5001] = { "Les affaires de Bijou", "Retrouvez les Affaires de Bijou et rapportez-les-lui. Bonne chance !" },
    [5002] = { "Message à Maxwell", "Rendez-vous dans les Steppes Ardentes et confiez les Renseignements de Bijou au maréchal Maxwell." },
    [5047] = { "Finkle Einhorn, à votre service !", "Parler à Malyfous Sombremartel à Long-Guet." },
    [5063] = { "La coiffe du savant écarlate", "Pour créer la Coiffe du savant écarlate, il faut rapporter les éléments suivants à Malyfous Sombremartel : 1 Peau de la Bête en parfait état ; 5 Coutures d'Abomination effilochées ; 8 Cristaux des arcanes ; 5 Fils écarlates enchantés.\n\nIl faudra aussi payer 50 pièces d’or pour le travail de fabrication." },
    [5065] = { "Les tablettes perdues de Mosh'aru", "Apportez la Troisième et la Quatrième tablette Mosh'aru au Prospecteur Botte-de-fer, à Tanaris." },
    [5067] = { "Jambières d'Arcana", "Pour fabriquer les Jambières d'Arcana, il faut rapporter les éléments suivants à Malyfous Sombremartel : 1 Peau de la Bête en parfait état ; 5 Coutures d'Abomination effilochées ; 5 Barres d'arcanite ; 5 Fluides d'embaumement de Murmegivre.\n\nIl faudra également payer 50 pièces d’or pour le travail de fabrication." },
    [5068] = { "La cuirasse carnassière", "Pour fabriquer la Cuirasse carnassière, il faut rapporter les éléments suivants à Malyfous Sombremartel : 1 Peau de la Bête en parfait état ; 10 Coutures d'Abomination effilochées ; 5 Barres d'arcanite ; 5 Peaux des ombres.\n\nIl faudra également payer 50 pièces d’or pour le travail de fabrication." },
    [5081] = { "Mission de Maxwell", "Se rendre au Pic Rochenoire et tuer le maître de guerre Voone, le généralissime Omokk, et le seigneur Wyrmthalak." },
    [5089] = { "Ordres du général Drakkisath", "Remettez les Ordres du général Drakkisath au maréchal Maxwell dans les Steppes Ardentes." },
    [5102] = { "La reddition du général Drakkisath", "Rendez-vous au Pic Rochenoire et tuez le général Drakkisath." },
    [5122] = { "Le médaillon de foi" },
    [5125] = { "La rétribution d'Aurius" },
    [5126] = { "L'histoire de Lorax", "Parler à Lorax. Écouter ce qu’il a à dire." },
    [5127] = { "La forge démoniaque", "Se rendre au pic Rochenoire et trouver Goraluk Brisenclume. Le tuer puis utiliser la Pique tachée de sang sur son cadavre. Après avoir siphonné son âme, la pique sera devenue Tachée d'âme.\n\nTrouver aussi la Cuirasse couverte de runes inachevée.\n\nRapporter la Pique tachée d'âme et la Cuirasse couverte de runes inachevée à Lorax au Berceau-de-l'Hiver." },
    [5160] = { "Le Protectorat de la matrone", "Aller jusqu’au Berceau-de-l'Hiver et trouver Haleh. Lui donner l’Ecaille d'Awbee." },
    [5161] = { "La colère du vol bleu", "Si vous souhaitez continuer, parlez à Haleh." },
    [5162] = { "La colère du vol bleu", "Parler à Jeziba dans les Maleterres. Il vit à Andorhal." },
    [5164] = { "Guide de l'Indocile", "Lire le Guide de l'Indocile." },
    [5166] = { "La cuirasse du vol chromatique", "Pour forger la Cuirasse du vol chromatique, il faut apporter les éléments suivants à Jeziba le « Sculpteur » :\n\n1 Carapace chromatique.\n\n10 Ecailles chromatiques brillantes.\n\n10 doses de Sang des héros.\n\n10 Coutures d'Abomination effilochées." },
    [5167] = { "Les cuissards du duelliste chromatique", "Pour forger les Cuissards de duelliste chromatique, il faut apporter les éléments suivants à Jeziba le « Sculpteur » :\n\n1 Carapace chromatique.\n\n10 Ecailles chromatiques brillantes.\n\n10 doses de Sang des héros.\n\n5 Peaux des ombres." },
    [5212] = { "La chair ne ment pas", "Récupérer 10 Échantillons de chair pestiférée à Stratholme puis les rapporter à Betina Bigglezink. Vous pensez que toutes les créatures de Stratholme possèdent de tels échantillons de chair." },
    [5213] = { "L'agent actif", "Se rendre jusqu’à Stratholme et fouiller les ziggourats. Trouver et ramener de nouvelles informations sur le Fléau à Betina Bigglezink." },
    [5214] = { "Le grand Fras Siabi", "Trouver le magasin de tabac de Fras Siabi dans Stratholme et récupérer une boîte de Tabac de Siabi. Retourner auprès de Smokey LaRue quand le travail est fait." },
    [5243] = { "Les demeures du Sacré", "Rendez-vous à Stratholme, au nord. Fouillez les caisses de fournitures qui encombrent la cité et récupérez 5 Eaux sacrées de Stratholme. Retournez auprès de Leonid Barthalomew le Révéré quand vous aurez récolté assez de fioles bénites." },
    [5251] = { "L'archiviste", "Voyager jusqu’à Stratholme et trouver l’Archiviste Galford de la Croisade écarlate. L’abattre et brûler les Archives écarlates." },
    [5262] = { "La vérité vient du ciel", "Apporter la Tête de Balnazzar au duc Nicholas Zverenhoff dans les Maleterres de l’Est." },
    [5263] = { "Au-dessus et au-delà", "S’aventurer dans Stratholme et tuer le baron Vaillefendre. Prendre sa tête et retourner auprès du duc Nicholas Zverenhoff." },
    [5264] = { "Seigneur Maxwell Tyrosus", "Parler au seigneur Maxwell Tyrosus. Il est à l’intérieur de l’église." },
    [5265] = { "Le Coffre d'argent", "Ouvrez le Coffre d'argent et prenez votre récompense." },
    [5281] = { "Âmes tourmentées", "Trouver Egan. Vous savez seulement qu’on l’a vu pour la dernière fois aux alentours de Stratholme." },
    [5282] = { "Âmes tourmentées", "Se servir de la Pétoire d'Egan sur les citoyens fantomatiques et spectraux de Stratholme. Quand les esprits sans repos se libèrent de leur enveloppes fantomatiques, utiliser de nouveau la Pétoire – ils seront enfin libres !\n\nLibérer 15 Esprits sans repos puis retourner auprès d’Egan." },
    [5341] = { "Fortune de la famille Barov", "S’aventurer jusqu’à la Scholomance et récupérer la fortune de la famille Barov. Cette fortune se compose de quatre titres de propriété : le titre de propriété de Caer Darrow ; le titre de propriété de Brill ; le titre de propriété de Moulin-de-Tarren ; et le titre de propriété d’Austrivage. Revenir auprès d’Alexi Barov quand la tâche est accomplie." },
    [5342] = { "Le dernier Barov", "Voyagez jusqu’au Camp du Noroît, dans le territoire de l’Alliance, et assassinez Weldon Barov. Prenez sa tête et revenez auprès d’Alexi Barov.\n\nAttention : Weldon sera probablement bien protégé par la racaille de l’Alliance." },
    [5343] = { "Fortune de la famille Barov", "S’aventurer jusqu’à la Scholomance et récupérer la fortune de la famille Barov. Cette fortune se compose de quatre titres de propriété : le titre de propriété de Caer Darrow ; le titre de propriété de Brill ; le titre de propriété de Moulin-de-Tarren ; et le titre de propriété d’Austrivage. Revenir auprès de Weldon Barov quand la tâche est accomplie." },
    [5344] = { "Le dernier Barov", "Voyager jusqu’à la Barricade - territoire de la Horde - et assassiner Alexi Barov. Prendre sa tête et revenir auprès de Weldon Barov.\n\nAttention : Alexi sera probablement bien protégé par les vandales de la Horde." },
    [5382] = { "Docteur Theolen Krastinov, le boucher", "Trouver le docteur Theolen Krastinov à l’intérieur de la Scholomance. Le tuer, puis brûler le Cadavre d’Eva Sarkhoff et le Cadavre de Lucien Sarkhoff. Retourner auprès d’Eva Sarkhoff quand la tâche est accomplie." },
    [5384] = { "Kirtonos le héraut", "Retournez à la Scholomance avec le Sang des innocents. Trouvez le porche et placez le Sang des innocents dans le brasero. Kirtonos viendra dévorer votre âme.\n\nCombattez vaillamment, sans perdre un pouce de terrain ! Détruisez Kirtonos et retournez auprès d’Eva Sarkhoff." },
    [5461] = { "L'humain, Ras Murmegivre", "Voyager jusqu’aux Hautes-terres Arathies, et aller aux ruines de Stromgarde. Fouiller Stromgarde pour trouver un Souvenir de la mémoire. Si une telle trouvaille est faite, rapporter l’objet au magistrat Marduke." },
    [5462] = { "Le moribond, Ras Murmegivre", "Voyager jusqu’à l’Espoir de lumière dans les Maleterres de l'Est et trouver Leonid Barthalomew le Révéré. Lui montrer le Souvenir de la mémoire et lui dire tout ce que vous avez découvert." },
    [5463] = { "Le cadeau de Menethil", "Voyager jusqu’à Stratholme et trouver le cadeau de Menethil. Placer le Souvenir de la mémoire sur le sol impie." },
    [5464] = { "Le cadeau de Menethil", "Apporter le Souvenir lié à Leonid Barthalomew dans les Maleterres de l’Est." },
    [5465] = { "Souvenir lié", "Retourner auprès du Magistrat Marduke à Caer Darrow. Lui montrer le Souvenir lié." },
    [5466] = { "La Liche, Ras Murmegivre", "Trouver Ras Murmegivre dans Scholomance. Après l’avoir trouvé, utiliser le Souvenir lié sur son visage mort-vivant. Si sa transformation en mortel réussit, l’abattre et prendre la Tête humaine de Ras Murmegivre. Apporter la tête au Magistrat Marduke." },
    [5515] = { "Sac des horreurs de Krastinov", "Trouver Jandice Barov dans Scholomance et la tuer. Sur son cadavre, récupérer le Sac des horreurs de Krastinov. Rapporter le sac à Eva Sarkhoff." },
    [5518] = { "La tenue d'ogre gordok", "Apportez 4 Rouleaux d'étoffe runique, 8 Cuirs robustes, 2 Fils runiques et du Tanin ogre à Noué Dédodevie. Il est actuellement enchaîné dans l’aile gordok de Hache-Tripes." },
    [5519] = { "La tenue d'ogre gordok" },
    [5522] = { "Leonid Barthalomew", "Apportez les Œufs congelés à Leonid Barthalomew dans les Maleterres de l’Est." },
    [5525] = { "Libérez Noué !" },
    [5526] = { "Fragment de la Gangrevigne", "Trouvez la Gangrevigne à Hache-Tripes et prenez-en un fragment. Il est probable que vous ne pourrez vous en emparer qu’après la mort d’Alzzin le Modeleur. Servez-vous du Reliquaire de Pureté pour conserver le fragment, et retournez à Reflet-de-Lune voir Rabine Saturna au village de Havrenuit." },
    [5527] = { "Un reliquaire de pureté", "Rendez-vous en Silithus et cherchez un Reliquaire de pureté dans les ruines du village de Sudevent. Si vous parvenez à le trouver, rapportez-le à Rabine Saturna à Havrenuit, Reflet-de-Lune." },
    [5528] = { "La dégustation gordok" },
    [5529] = { "Portée contaminée", "Tuer 20 Jeunes pestiférés, puis retourner auprès de Betina Bigglezink à la Chapelle de l’Espoir de Lumière." },
    [5531] = { "Betina Bigglezink", "Apportez les Œufs congelés à Betina Bigglezink." },
    [5542] = { "Chiens-démons", "Tuer 20 Chiens pestiférés chétifs, 5 Chiens pestiférés et 5 Chiens pestiférés frénétiques. Retourner voir Tirion Fordring quand la mission sera terminée." },
    [5543] = { "Ciel couleur de sang", "Tuer 30 Chauves-souris pestiférées, puis retourner voir Tirion Fordring." },
    [5544] = { "Larve putride", "Chercher les Larves putrides et les Dévoreurs de la région. Les tuer et récupérer leur viande. Retourner voir Tirion Fordring quand 15 pièces de Chair de Ver putride auront été récupérées." },
    [5582] = { "L'écaille de dragon luisante", "Apportez l’Ecaille de dragon luisante à Betina Bigglezink à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est." },
    [5722] = { "À la recherche de la sacoche perdue", "Fouiller le Gouffre de Ragefeu pour trouver le cadavre de Maur Totem-sinistre et tout élément intéressant." },
    [5723] = { "Tester la force de l'ennemi", "Chercher le gouffre de Ragefeu dans Orgrimmar, puis tuer 8 Troggs Ragefeu et 8 Chamans Ragefeu avant de revenir auprès de Rahauro aux Pitons-du-Tonnerre." },
    [5724] = { "Rapporter la sacoche perdue", "Apporter la Sacoche du Totem-sinistre à Rahauro aux Pitons-du-Tonnerre." },
    [5725] = { "Le pouvoir de détruire...", "Apportez les livres « Les Sorts de l’Ombre » et « Les Incantations du Néant » à Varimathras, à Fossoyeuse." },
    [5726] = { "Ennemis cachés", "Apporter un Insigne de lieutenant à Thrall à Orgrimmar." },
    [5727] = { "Ennemis cachés", "Apporter l'Insigne du Lieutenant à Neeru Lamefeu et lui parler. Essayer de déterminer s'il vous croit membre de la Lame ardente puis retourner voir Thrall à Orgrimmar." },
    [5728] = { "Ennemis cachés", "Tuer Bazzalan et Jergosh l'Invocateur avant de retourner voir Thrall à Orgrimmar." },
    [5729] = { "Ennemis cachés", "Parler à Neeru Lamefeu à Orgrimmar." },
    [5730] = { "Ennemis cachés", "Parlez à Thrall à Orgrimmar et dites-lui ce que vous avez appris." },
    [5742] = { "Rédemption", "Écouter ce que Tirion Fordring a à dire." },
    [5761] = { "Tuer la bête", "Pénétrer dans le Gouffre de Ragefeu et tuer Taragaman l'Affameur, puis rapporter son cœur à Neeru Lamefeu à Orgrimmar." },
    [5781] = { "Aux mémoires perdues", "Aller au caveau de Zaeldarr - situé dans la section la plus au sud des Maleterres de l’Est - et récupérer le Marteau de Taelan. Retourner auprès de Tirion Fordring après avoir accompli la mission." },
    [5845] = { "De l'honneur perdu", "Se rendre à Valnord, dans la région nord-est des Maleterres de l’Est, et récupérer le Symbole de l’honneur perdu. Revenir auprès de Tirion Fordring quand la tâche est accomplie." },
    [5846] = { "L'amour et la famille", "Voyager jusqu’à l’île de Caer Darrow, dans la région centre-sud des Maleterres, et chercher un indice de l’emplacement du tableau." },
    [5848] = { "De l'amour et de la famille", "Se rendre à Stratholme, dans la partie nord des Maleterres. C’est dans le Bastion écarlate que se trouve le tableau De l'amour et de la famille, caché derrière une autre peinture représentant les lunes jumelles.\n\nRapporter le tableau à Tirion Fordring." },
    [5861] = { "Trouver Myranda", "Se rendre au tombeau d’Uther, au sud des Maleterres. Montrer à Myranda la Mégère le Don de Tirion." },
    [5862] = { "Le subterfuge écarlate", "Parlez à Myranda pour obtenir l’Illusion écarlate. Allez à Âtreval pendant que vous êtes sous l’effet de l’Illusion écarlate, et apportez le Don de Tirion au généralissime Taelan Fordring.\n\nÂtreval se trouve au nord, et Taelan devrait se trouver à l’intérieur du Donjon de Mardenholde." },
    [5944] = { "En rêve", "Escortez Taelan Fordring jusqu'à la sortie d'Âtreval." },
    [6022] = { "Tuer utile", "Allez à l'est à la Croisée de Corin et détruisez les membres du Fléau qui habitent la ville. Rassemblez 7 morceaux de Pourriture vivante en moins de 10 minutes. Utilisez le Mortier et le Pilon pour réduire la Pourriture vivante en Pourriture coagulée." },
    [6042] = { "Les petits soucis de la non-vie", "Tuer 20 Chauves-souris pestiférées nuisibles et 10 Chauves-souris pestiférées monstrueuses. Retourner voir Nathanos le Flétrisseur quand ce sera fait." },
    [6133] = { "L'ordre du seigneur forestier", "Aller vers la frontière nord des Maleterres de l’Est et récupérer le Registre de Quel'Thalas. L’objet se trouve quelque part dans le gîte de Quel'Lithien.\n\nTuer également 8 Forestiers, 8 Eclaireurs et 8 Bûcherons." },
    [6135] = { "Crépuscaile, oh comme je te hais !", "Trouver Crépuscaile et la tuer. Récupérer une Touffe de fourrure de Crépuscaile sur son cadavre, puis l’apporter à Nathanos le Flétrisseur.\n\nIl paraît que Crépuscaile hante les terres qui se trouvent au nord de la ferme des Marris." },
    [6136] = { "Le corpulent", "Trouver Creusechair, dans les terres au nord des Maleterres de l’Est, et le tuer. Retourner voir Nathanos le Flétrisseur quand la mission sera terminée." },
    [6163] = { "Ramstein", "Aller à Stratholme et tuer Ramstein Grandgosier. Prendre sa tête, et l’apporter à Nathanos." },
    [6402] = { "Le rendez-vous à Hurlevent", "Voyagez jusqu'à Hurlevent et rendez-vous aux portes de la ville. Parlez à l'écuyer Rowe, afin qu'il informe le maréchal Windsor de votre arrivée." },
    [6403] = { "La grande mascarade", "Suivre Reginald Windsor dans Hurlevent. Le protéger contre toute menace !" },
    [6501] = { "L'Œil de dragon", "Vous devez écumer le monde pour pouvoir rétablir le pouvoir du Fragment de l'Oeil de dragon. La seule information dont vous disposez à propos de cette chose, c’est qu’elle existe." },
    [6502] = { "Amulette drakefeu", "Récupérer le Sang du Champion des dragons noirs sur le général Drakkisath. Il se trouve dans sa salle du trône, derrière les Halls d'Ascension, sur le Pic Rochenoire." },
    [6521] = { "Une alliance impie", "Apporter la Tête de l'Ambassadeur Malcin à Bragor Poing-de-sang, à Fossoyeuse." },
    [6522] = { "Une alliance impie", "Apporter le Petit parchemin à Bragor Poing-de-sang, au Quartier royal, à Fossoyeuse." },
    [6561] = { "L'infamie de Brassenoire", "Apportez la tête du Seigneur du Crépuscule Kelris à Bashana Totem-runique, aux Pitons-du-Tonnerre." },
    [6562] = { "Problèmes dans les profondeurs", "Parlez à Je'neu Sancrea, en Orneval." },
    [6563] = { "L'essence d'Aku'Mai", "Apportez 20 Saphirs d'Aku'Mai à Je'neu Sancrea, en Orneval." },
    [6564] = { "Allégeance aux Dieux très anciens", "Apportez la Note humide à Je'neu Sancrea en Orneval." },
    [6565] = { "Allégeance aux Dieux très anciens", "Tuer Lorgus Jett." },
    [6566] = { "Ce que le vent apporte", "Écoutez Thrall." },
    [6567] = { "Le Champion de la Horde", "Chercher Rokaro au village Proie-de-l'Ombre en Désolace." },
    [6568] = { "Maîtresse en tromperie", "Apporter la Lettre de Rokaro à Myranda la Mégère, dans les Maleterres de l’Ouest." },
    [6569] = { "Illusions d'Oculus", "Aller au Pic Rochenoire et collecter 20 Yeux de draconide noir. Retourner voir Myranda la Mégère quand la tâche sera terminée." },
    [6570] = { "Brandeguerre", "Aller à la Tourbière du Ver, dans le Marécage d'Âprefange, et chercher la Tanière de Brandeguerre. Une fois à l’intérieur, porter l’Amulette de subversion draconique, et parler à Brandeguerre." },
    [6582] = { "L'épreuve des crânes, Clairvoyant", "Vous devez trouver Clairvoyant, le drake champion du Vol bleu, et le tuer. Arracher son crâne à son cadavre, et le rapporter à Brandeguerre.\n\nClairvoyant se trouve au Berceau-de-l'Hiver." },
    [6583] = { "L'épreuve des crânes, Somnus", "Détruire le Champion drake du Vol vert, Somnus. Arracher son crâne à son cadavre, puis le rapporter à Brandeguerre." },
    [6584] = { "L'épreuve des crânes, Chronalis", "Chronalis, enfant de Nozdormu, garde les Grottes du temps, dans le Désert de Tanaris. Tuez-le et rapportez son crâne à Brandeguerre." },
    [6585] = { "L'épreuve des crânes, Axtroz", "Aller à Grim Batol et traquer Axtroz, le Champion drake du Vol rouge. Le tuer et arracher son crâne, puis l’apporter à Brandeguerre." },
    [6601] = { "Ascension...", "Il semble que la comédie soit finie. Vous savez que l’Amulette de subversion draconique, créée par Myranda la Mégère, ne fonctionnera pas à l’intérieur du pic Rochenoire. Peut-être devriez-vous trouver Rokaro et lui exposer votre fâcheuse situation. Montrez-lui l'Amulette drakefeu terne. Avec un peu de chance, il saura quoi faire." },
    [6602] = { "Le sang du champion des dragons noirs", "Aller au Pic Rochenoire, et tuer le général Drakkisath. Récupérer son sang et l'apporter à Rokaro." },
    [6626] = { "L'hôte du mal", "Tuer 8 Gardes de guerre Tranchebauge, 8 Tisseurs d'épines Tranchebauge et 8 Sectateur de la Tête de mort, puis retourner voir Myriam Chantelune, à l’entrée des Souilles de Tranchebauge." },
    [6627] = { "L'épreuve de la Connaissance", "Réussir à répondre à la question de Braug Esprit-troublé, puis lui reparler. Il se trouve dans les Serres-Rocheuses." },
    [6628] = { "L'épreuve de la Connaissance", "Réussir à répondre à la question de Parqual Fintallas, puis lui reparler. Il se trouve à Fossoyeuse." },
    [6804] = { "Eau empoisonnée", "Utiliser l’Aspect de Neptulon sur les élémentaires empoisonnés des Maleterres de l’Est. Apporter 12 Bracelets discordants et l’Aspect de Neptulon au duc Hydraxis, en Azshara." },
    [6805] = { "Tempêtes", "Tuer 15 Tempétueux de poussière et 15 Grondeurs du désert, puis retourner voir le duc Hydraxis, en Azshara." },
    [6821] = { "Œil du Prophète ardent", "Apportez l’Oeil du Prophète ardent au duc Hydraxis, en Azshara." },
    [6822] = { "Le Cœur du Magma", "Tuez 1 Seigneur du Feu, 1 Géant de lave, 1 Chien antique du Magma et 1 Surgisseur de lave, puis retournez voir le duc Hydraxis, en Azshara." },
    [6823] = { "Agent de Hydraxis", "Parvenir au niveau de réputation Honoré auprès des Hydraxiens, puis parler au duc Hydraxis, en Azshara." },
    [6824] = { "Les mains de l'ennemi", "Apportez les Mains de Lucifron, de Sulfuron, de Gehennas et de Shazzrah au duc Hydraxis, en Azshara." },
    [6921] = { "Parmi les ruines", "Apportez le Noyau de la Brasse à Je'neu Sancrea, à l’Avant-poste de Zoram'gar, en Orneval." },
    [6922] = { "Baron Aquanis", "Apportez le Globe d'eau étrange à Je'neu Sancrea, dans les Profondeurs de Brassenoire." },
    [6981] = { "L'Éclat luminescent", "Allez à Cabestan pour trouver quelqu'un qui puisse vous en dire plus sur l'Éclat luminescent.\n\nPuis livrez l'Éclat, selon les instructions." },
    [7028] = { "Forces maléfiques retorses", "Collecter 15 Gravures de cristaux théradriques pour Saule, en Désolace." },
    [7029] = { "La corruption de Vylelangue", "Remplir la Fiole céruléenne renforcée, au Bassin de cristal orange, dans Maraudon.\n\nEn faire usage sur les Vignes de Vylevrille pour forcer les Engeances Noxcives corrompues à en sortir.\n\nSoigner 8 plantes en tuant les Engeances Noxcives, puis retourner voir Vark Balafre-glorieuse, à Proie-de-l'Ombre." },
    [7041] = { "La corruption de Vylelangue", "Remplir la Fiole céruléenne renforcée, au Bassin de cristal orange dans Maraudon.\n\nEn faire usage sur les vignes de Vylevrille pour forcer les Engeances Noxcives corrompues à en sortir.\n\nSoigner 8 plantes en tuant les Engeances, puis retourner voir Talendria, à la Combe de Nijel." },
    [7044] = { "Légendes de Maraudon", "Retrouver les deux parties du Sceptre de Celebras : le Bâtonnet celebrien et le Diamant celebrien.\n\nTrouvez un moyen de parler à Celebras." },
    [7046] = { "Le sceptre de Celebras", "Aidez Celebras le Racheté pendant qu'il recrée le Sceptre de Celebras.\n\nParlez-lui après la réussite du rituel." },
    [7064] = { "Corruption de la terre et de la graine", "Anéantir la princesse Theradras et retourner voir Selendra près de Proie-de-l'Ombre, en Désolace." },
    [7065] = { "Corruption de la terre et de la Graine", "Tuer la princesse Theradras, et retourner voir le Gardien Marandis, à la Combe de Nijel en Désolace." },
    [7066] = { "La graine de la vie", "Chercher Remulos à Reflet-de-Lune, et lui donner la Graine de la vie." },
    [7067] = { "Les instructions du Paria", "Lisez les Instructions du Paria. Après cela, trouvez l'Amulette d'union de Maraudon et rapportez-la au Paria centaure, dans le sud de Désolace." },
    [7068] = { "Fragments d'Ombréclat", "Récupérez 10 Fragments d'Ombréclats dans Maraudon, et rapportez-les à Uthel'nay, à Orgrimmar." },
    [7070] = { "Fragments d'Ombréclat", "Récupérez 10 Fragments d'Ombréclats à Maraudon, et les apporter à l'archimage Tervosh, dans le marécage d'Âprefange." },
    [7201] = { "Le dernier élément", "Partir pour les Profondeurs de Rochenoire et trouver 10 Essences des éléments. Commencer vos recherches par les golems et par les créateurs de golems. Vivian Lagrave a aussi marmonné quelque chose à propos d'élémentaires." },
    [7429] = { "Libérez Noué !" },
    [7441] = { "Pusillin et l'Ancien Azj'Tordin", "Rendez-vous à Hache-Tripes et trouvez le diablotin Pusillin. Persuadez-le par tous les moyens de vous rendre le Livre d’Incantations d’Azj’Tordin.\n\nSi vous parvenez à le récupérer, retournez voir Azj’Tordin au Pavillon de Lariss, en Féralas." },
    [7461] = { "Folie intérieure", "Vous devez détruire les gardiens qui protègent les 5 Pylônes qui alimentent la Prison d’Immol’thar. Une fois que les Pylônes seront coupés, le champ de force qui entoure Immol’thar se dissipera.\n\nEntrez dans la Prison d’Immol’thar et éradiquez l’infâme démon qui se trouve en son cœur. Enfin, affrontez le prince Tortheldrin à l’Athenaeum.\n\nLorsque vous aurez terminé, retournez voir l’Ancienne des Shen’dralar dans la cour." },
    [7462] = { "Le trésor des Shen'dralar", "Retournez à l’Athenaeum et trouvez le Trésor des Shen’dralar. Prenez votre récompense !" },
    [7463] = { "Rafraîchissement arcanique", "Rendez-vous dans le quartier de Crochebois de Hache-Tripes et tuez Hydrogénos, l’élémentaire de l’eau. Retournez voir le Gardien du savoir Lydros à l’Athenaeum avec l’Essence d’Hydrogénos." },
    [7481] = { "Légendes elfiques", "Fouillez Hache-Tripes à la recherche de Kariel Winthalus. Lorsque vous aurez des informations, donnez-les au Sage Korolusk de Camp Mojache." },
    [7482] = { "Légendes elfiques", "Fouillez Hache-Tripes à la recherche de Kariel Winthalus. Lorsque vous aurez des informations, donnez-les à l’Erudite Roncerune, à Pennelune." },
    [7483] = { "Libram de rapidité", "Apportez un Libram de rapidité, 1 Diamant noir parfait, 2 Grands éclats brillants et 2 doses de Sang des héros au Gardien du savoir Lydros à Hache-Tripes pour recevoir un Arcanum de rapidité." },
    [7484] = { "Libram de focalisation", "Apportez un Libram de focalisation, 1 Diamant noir en parfait état, 4 Grands éclats brillants et 2 Peaux des ombres au Gardien du savoir Lydros à Hache-Tripes pour recevoir un arcanum de focalisation." },
    [7485] = { "Libram de protection", "Apportez un Libram de protection, 1 Diamant noir en parfait état, 2 Grands éclats brillants et 1 Couture d'abomination effilochée au Gardien du savoir Lydros à Hache-Tripes pour recevoir un Arcanum de protection." },
    [7486] = { "La récompense du héros", "Allez chercher votre récompense dans le Coffre d’Hydraxis." },
    [7488] = { "Le filet de Lethtendris", "Rapportez le Filet de Lethtendris à Latronicus Lancelune au bastion de Pennelune en Féralas." },
    [7489] = { "Le filet de Lethtendris", "Ramenez le Filet de Lethtendris à Talo Sabot-de-ronce au Camp Mojache, en Féralas." },
    [7490] = { "Victoire pour la Horde !", "Apportez la Tête d’Onyxia à Garrosh à Orgrimmar." },
    [7491] = { "Pour que tous voient", "Allez voir le seigneur Runthak dans la Vallée de la Force." },
    [7493] = { "Le voyage commence à peine" },
    [7495] = { "Victoire pour l'Alliance !", "Apportez la Tête d’Onyxia au roi Varian Wrynn à Hurlevent." },
    [7496] = { "Célébrer le triomphe", "Allez voir le major Mattingly dans la vallée des Héros." },
    [7497] = { "Le voyage commence à peine" },
    [7503] = { "La plus grande race de chasseurs", "Rendez ce livre à ses légitimes propriétaires." },
    [7507] = { "Le guide de Dagharn", "Rendez “Le guide de Dagharn du tueur de dragons“ à l’Athenaeum." },
    [7508] = { "Forger Quel'Serrar", "Donnez la Lame elfique inachevée au Gardien du savoir Lydros." },
    [7509] = { "Forger Quel'Serrar", "Vous devez amener Onyxia à cracher le feu sur la Lame ancienne brute. Lorsque ce sera fait, ramassez la Lame ancienne chauffée. Attention, elle ne restera pas chaude éternellement. Le temps est très important.\n\nAvant de revenir me voir, il vous faudra tuer la bête et plonger la Lame ancienne chauffée dans son cadavre.\n\nSi vous y parvenez, Quel’Serrar sera à vous." },
    [7562] = { "Mor'zul Porte-sang", "Allez voir Mor'zul Porte-sang à l'Autel des Tempêtes, dans les Steppes Ardentes." },
    [7563] = { "Rage de sang", "Apportez 30 bouteilles de Sang de bêtes déchaînées à Mor'zul Porte-sang dans les Steppes Ardentes." },
    [7564] = { "Gorzeeki Fouregard", "Apportez la Caisse de sang à Gorzeeki Fouregard à l'Autel des tempêtes, dans les Steppes Ardentes." },
    [7629] = { "Livraison de diablotin", "Apportez le Diablotin en bouteille au laboratoire d'alchimie de la Scholomance. Une fois le parchemin créé, rapportez la bouteille à Gorzeeki Fouregard." },
    [7637] = { "L'accent sur le sacrifice", "Rendez-vous à Forgefer et procurez-vous l’Encensoir d’exorcisme du grand prêtre Rohan. Pour vous le procurer, il vous faudra verser une donation de 150 pièces d’or." },
    [7638] = { "Le seigneur Grayson Brisombre", "Parler au seigneur Grayson Brisombre dans le Quartier de la Cathédrale de Hurlevent." },
    [7639] = { "Des preuves de jugement", "Ramener l’Encensoir d’exorcisme au seigneur Grayson Brisombre, dans le Quartier de cathédrale de Hurlevent." },
    [7640] = { "Exorciser Val-Terreur", "Servez-vous de l’Encensoir d’exorcisme pour chasser les esprits qui tourmentent Val-Terreur. Lorsque vous aurez tué 25 Esprits de Val-Terreur, retournez voir le seigneur Grayson Brisombre dans le Quartier de la Cathédrale de Hurlevent." },
    [7641] = { "L'œuvre de Grimand Elmore", "Parlez à Grimand Elmore dans le Quartier des Nains de Hurlevent." },
    [7642] = { "Une ribambelle d'objets", "Apporter 40 Etoffes runiques, 6 Barres d’arcanite, 10 Larmes d’Arthas, 5 Fioles d’eau sacrée de Stratholme, et 150 pièces d’or à Grimand Elmore, au Quartier des Nains de Hurlevent." },
    [7643] = { "L'ancien esprit équin", "Procurez-vous un aliment pour chevaux capable de nourrir un esprit équin. Il semble que Merideth Carlson, à Austrivage, sache en fabriquer.\n\nEnsuite, rendez-vous au donjon de Hache-Tripes en Féralas, et tuez Tendris Crochebois. Sa mort libérera l’Ancien esprit équin. Nourrissez-le avec l’aliment spécial afin de l’apaiser. Enfin, donnez-lui le Caparaçon d’arcanite pour qu’il le bénisse." },
    [7644] = { "Le caparaçon en arcanite béni", "Retourner dans le Quartier de la Cathédrale de Hurlevent avec le Caparaçon d’arcanite béni pour voir le seigneur Grayson Brisombre." },
    [7646] = { "Le Clairvoyant", "Apportez un Diamant d’Azeroth et un Diamant noir en parfait état au seigneur Grayson Brisombre dans le Quartier de la Cathédrale de Hurlevent." },
    [7667] = { "Assistance matérielle", "Si vous voulez aider Sagorne Rôdeur-des-crêtes de la Vallée de la Sagesse d'Orgrimmar, apportez-lui un Diamant d’Azeroth et un Diamant noir en parfait état." },
    [7668] = { "La menace de Ravassombre", "Servez-vous du Clairvoyant au centre du sous-sol du Grand ossuaire de la Scholomance. Cela attirera des esprits que vous devrez combattre. Les vaincre fera apparaître le Chevalier de la mort Ravassombre. Tuez-le.\n\nRapportez la Tête de Ravassombre à Sagorne Rôdeur-des-crêtes de la Vallée de la Sagesse, à Orgrimmar." },
    [7669] = { "Retour au Grand ossuaire" },
    [7761] = { "Les instructions de Main-noire", "Cet orc est stupide. Il semble que vous deviez trouver un moyen d’obtenir la Marque de Drakkisath pour accéder à l’Orbe de commandement.\n\nD’après la lettre, la Marque est gardée par le général Drakkisath. Vous devriez peut-être enquêter." },
    [7848] = { "Harmonisation avec le Cœur du Magma", "Aventurez-vous jusqu'au portail d'entrée du Cœur du Magma dans les profondeurs de Rochenoire et récupérez un Fragment du Magma. Lorsque ce sera fait, retournez voir Lothos Ouvrefaille au mont Rochenoire." },
    [7877] = { "Le trésor des Shen'dralar", "Retournez à l’Athenaeum et trouvez le Trésor des Shen’dralar. Prenez votre récompense !" },
    [8181] = { "La confrontation avec Yeh'kinya", "Parlez à Yeh'kinya." },
    [8182] = { "La Main de Rastakhan", "Parlez à Molthor à Strangleronce." },
    [8905] = { "Une proposition sérieuse", "Procurez-vous 15 Échantillons de sang du Berceau-de-l’Hiver et 20 pièces d’or, et apportez-les avec une paire de Brassards du Cœur-sauvage à Deliana à Forgefer." },
    [8906] = { "Une proposition sérieuse", "Procurez-vous 15 Échantillons de sang du Berceau-de-l'hiver et 20 pièces d’or, et apportez-les avec une paire de Manchettes de bestiaire à Deliana à Forgefer." },
    [8907] = { "Une proposition sérieuse", "Procurez-vous 15 Échantillons de sang du Berceau-de-l’Hiver et 20 pièces d’or, et apportez-les avec une paire de Bracelets de magistère à Deliana à Forgefer." },
    [8908] = { "Une proposition sérieuse", "Procurez-vous 15 Échantillons de sang du Berceau-de-l’Hiver et 20 pièces d’or, et apportez-les avec une paire de Brassards de Sancteforge à Deliana à Forgefer." },
    [8909] = { "Une proposition sérieuse", "Procurez-vous 15 Échantillons de sang du Berceau-de-l’Hiver et 20 pièces d’or, et apportez-les avec une paire de Brassards de dévot à Deliana à Forgefer." },
    [8910] = { "Une proposition sérieuse", "Procurez-vous 15 Échantillons de sang du Berceau-de-l’Hiver et 20 pièces d’or, et apportez-les avec une paire de Bracelets Sombreruse à Deliana à Forgefer." },
    [8911] = { "Une proposition sérieuse", "Procurez-vous 15 Échantillons de sang du Berceau-de-l’Hiver et 20 pièces d’or, et apportez-les avec une paire de Brassards de Brume-funeste à Deliana à Forgefer." },
    [8912] = { "Une proposition sérieuse", "Procurez-vous 15 Échantillons de sang du Berceau-de-l’Hiver et 20 pièces d’or, et apportez-les avec une paire de Brassards de vaillance à Deliana à Forgefer." },
    [8913] = { "Une proposition sérieuse", "Procurez-vous 15 Echantillons de venin de Silithus et 20 pièces d’or, et apportez-les avec une paire de Brassards du Cœur-sauvage à Mokvar, à Orgrimmar." },
    [8914] = { "Une proposition sérieuse", "Procurez-vous 15 Echantillons de venin de Silithus et 20 pièces d’or, et apportez-les avec une paire de Manchettes de bestiaire à Mokvar, à Orgrimmar." },
    [8915] = { "Une proposition sérieuse", "Procurez-vous 15 Echantillons de venin de Silithus et 20 pièces d’or, et apportez-les avec une paire de Bracelets de magistère à Mokvar, à Orgrimmar." },
    [8916] = { "Une proposition sérieuse", "Procurez-vous 15 Echantillons de venin de Silithus et 20 pièces d’or, et apportez-les avec une paire de Brassards de dévot à Mokvar, à Orgrimmar." },
    [8917] = { "Une proposition sérieuse", "Procurez-vous 15 Echantillons de venin de Silithus et 20 pièces d’or, et apportez-les avec une paire de Bracelets Sombreruse à Mokvar, à Orgrimmar." },
    [8918] = { "Une proposition sérieuse", "Procurez-vous 15 Echantillons de venin de Silithus et 20 pièces d’or, et apportez-les avec une paire de Bracelets des éléments à Mokvar, à Orgrimmar." },
    [8919] = { "Une proposition sérieuse", "Procurez-vous 15 Echantillons de venin de Silithus et 20 pièces d’or, et apportez-les avec une paire de Brassards de Brume-funeste à Mokvar, à Orgrimmar." },
    [8920] = { "Une proposition sérieuse", "Procurez-vous 15 Echantillons de venin de Silithus et 20 pièces d’or, et apportez-les avec une paire de Brassards de vaillance à Mokvar, à Orgrimmar." },
    [8921] = { "L'alambic ectoplasmique", "Retournez voir Mux Brouillemana à Gadgetzan avec 1 Convertisseur d’arcanite délicat, 4 Essences éternelles supérieures, 10 Huiles de pierre-écaille, 25 Cendres volcaniques et 40 pièces d’or." },
    [8922] = { "Un objet surnaturel", "Apportez le Récipient de sang scellé à Mux Brouillemana, à Gadgetzan en Tanaris." },
    [8923] = { "Un objet surnaturel", "Remettez le Récipient de venin scellé à Mux Brouillemana, à Gadgetzan." },
    [8924] = { "La chasse aux ectoplasmes", "Utilisez l’Alambic ectoplasmique à proximité de morts-vivants désincarnés pour recueillir 12 Ectoplasmes brûlés en Silithus, 12 Ectoplasmes glacés au Berceau-de-l’Hiver et 12 Ectoplasmes stables dans les Maleterres de l’Est. Remettez à Mux Brouillemana à Gadgetzan. Il veut aussi récupérer l'Alambic ectoplasmique." },
    [8925] = { "Une source d’énergie portable", "Trouvez le Seigneur-magma Bokk dans les Steppes ardentes, prenez son Cœur de magma et rapportez-le à Mux Brouillemana, à Gadgetzan." },
    [8926] = { "Une juste compensation", "Apportez une Ceinture du Cœur-sauvage et une paire de Gants du Cœur-sauvage à Deliana à Forgefer." },
    [8927] = { "Une juste compensation", "Apportez une Ceinture du Cœur-sauvage et une paire de Gants du Cœur-sauvage à Mokvar à Orgrimmar." },
    [8928] = { "Un marchand à éclipses", "Trouvez un diablotin qui vivrait dans une caverne à l'entrée de la gorge du Sombre murmure, au sud du Berceau-de-l’Hiver. Achetez-lui un Bâtonnet élémentaire de corruption, puis retournez voir Mux Brouillemana à Gadgetzan." },
    [8929] = { "À la recherche d'Anthion", "Utilisez le Révélateur de fantômes extradimensionnel à l’entrée de Stratholme et parlez au fantôme d’Anthion Harmon." },
    [8930] = { "À la recherche d'Anthion", "Utilisez le Révélateur de fantômes extradimensionnel à l'entrée de Stratholme, et parlez au fantôme d'Anthion Harmon." },
    [8931] = { "Une juste compensation", "Apportez une Ceinture de bestiaire et une paire de Gants de bestiaire à Deliana à Forgefer." },
    [8932] = { "Une juste compensation", "Apportez une Ceinture de magistère et une paire de Gants de magistère à Deliana à Forgefer." },
    [8933] = { "Une juste compensation", "Apportez une Ceinture de Sancteforge et une paire de Gantelets de Sancteforge à Deliana à Forgefer." },
    [8934] = { "Une juste compensation", "Apportez une Ceinture de dévot et une paire de Gants de dévot à Deliana à Forgefer." },
    [8935] = { "Une juste compensation", "Apportez une Ceinture Sombreruse et une paire de Gants Sombreruse à Deliana à Forgefer." },
    [8936] = { "Une juste compensation", "Apportez une Ceinture de Brume-funeste et des Gants de Brume-funeste à Deliana à Forgefer." },
    [8937] = { "Une juste compensation", "Apportez une Ceinture de vaillance et une paire de Gantelets de vaillance à Deliana à Forgefer." },
    [8938] = { "Une juste compensation", "Apportez une Ceinture de bestiaire et une paire de Gants de bestiaire à Mokvar à Orgrimmar." },
    [8939] = { "Une juste compensation", "Apportez une Ceinture de magistère et une paire de Gants de magistère à Mokvar à Orgrimmar." },
    [8940] = { "Une juste compensation", "Apportez une Ceinture de dévot et une paire de Gants de dévot à Mokvar à Orgrimmar." },
    [8941] = { "Une juste compensation", "Apportez une Ceinture Sombreruse et une paire de Gants Sombreruse à Mokvar à Orgrimmar." },
    [8942] = { "Une juste compensation", "Apportez une Corde des éléments et une paire de Gantelets des éléments à Mokvar à Orgrimmar." },
    [8943] = { "Une juste compensation", "Apportez une Ceinture de Brume-funeste et des Gants de Brume-funeste à Mokvar à Orgrimmar." },
    [8944] = { "Une juste compensation", "Apportez une Ceinture de vaillance et une paire de Gantelets de vaillance à Mokvar à Orgrimmar." },
    [8945] = { "La supplique du mort", "Entrez à Stratholme et sauvez Ysida Harmon du baron Vaillefendre." },
    [8946] = { "Une preuve de vie", "Remettez le Médaillon d’Ysida à Anthion Harmon, dans les Maleterres de l’Est." },
    [8947] = { "L'étonnante requête d'Anthion", "Remettre 3 Barres de sombrefer, 20 Cuirs enchantés, 3 Etoffes lunaires et 4 Peaux robustes traitées à Anthion Harmon dans les Maleterres de l’Est." },
    [8948] = { "Le vieil ami d'Anthion", "Apportez la Bannière de défi incomplète à Farlin Sculpteflore, dans la bibliothèque de Hache-Tripes." },
    [8949] = { "La vendetta de Falrin", "Collecter 25 Perles de guerre ogres à l’intérieur de Hache-Tripes ou du Pic Rochenoire, puis revenir voir Falrin Sculpteflore, à l'intérieur de l'Athenaeum à Hache-Tripes." },
    [8950] = { "L'enchantement du provocateur", "Apportez les choses suivantes à Falrin Sculpteflore dans Hache-Tripes : 1 Essence de spectre railleur, 4 Runes ténébreuses et 8 Grands éclats brillants." },
